for ticker,a in x.items():
 market=a['price']*a['shares'];ev=market+a['debt_book']+a['nci']-a['cash']-a['nonoperating_investments'];ebit=a['ebit_reported']-a['nonrecurring_operating_income'];r={'ticker':ticker,'price':a['price'],'market_cap':market,'dated_capital_EV':ev,'reported_TTM_revenue':a['revenue'],'reported_TTM_EBIT':a['ebit_reported'],'normalized_operating_EBIT_not_cycle_midpoint':ebit,'EV_sales':ev/a['revenue'],'EV_reported_EBIT':ev/a['ebit_reported'],'EV_normalized_EBIT':ev/ebit}
